import heapq

def match(orders):
    trades = []
    buy_book = []  # heap of (-price, seq, id)
    sell_book = []  # heap of (price, seq, id)
    orders_info = {}  # id -> {'side','price','qty','active'}
    seq_counter = [0]

    def add_resting(oid, side, price, qty, seq):
        orders_info[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True, 'seq': seq}
        if side == 'buy':
            heapq.heappush(buy_book, (-price, seq, oid))
        else:
            heapq.heappush(sell_book, (price, seq, oid))

    def match_order(side, price, qty, incoming_id, is_market=False):
        # price is None if market order (no limit)
        remaining = qty
        if side == 'buy':
            book = sell_book
            while remaining > 0 and book:
                top_price, top_seq, top_id = book[0]
                info = orders_info.get(top_id)
                if info is None or not info['active']:
                    heapq.heappop(book)
                    continue
                if not is_market and price is not None and top_price > price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([incoming_id, top_id, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(book)
                # else stays at top, keep in place (still valid entry)
            return remaining
        else:
            book = buy_book
            while remaining > 0 and book:
                neg_price, top_seq, top_id = book[0]
                top_price = -neg_price
                info = orders_info.get(top_id)
                if info is None or not info['active']:
                    heapq.heappop(book)
                    continue
                if not is_market and price is not None and top_price < price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([top_id, incoming_id, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                    heapq.heappop(book)
            return remaining

    for order in orders:
        typ = order[0]
        if typ == 'limit':
            _, oid, side, price, qty = order
            seq = seq_counter[0]
            seq_counter[0] += 1
            remaining = match_order(side, price, qty, oid, is_market=False)
            if remaining > 0:
                add_resting(oid, side, price, remaining, seq)
            else:
                orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False, 'seq': seq}
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            seq = seq_counter[0]
            seq_counter[0] += 1
            remaining = match_order(side, price, qty, oid, is_market=False)
            orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False, 'seq': seq}
        elif typ == 'market':
            _, oid, side, qty = order
            seq = seq_counter[0]
            seq_counter[0] += 1
            remaining = match_order(side, None, qty, oid, is_market=True)
            orders_info[oid] = {'side': side, 'price': None, 'qty': 0, 'active': False, 'seq': seq}
        elif typ == 'cancel':
            _, oid = order
            info = orders_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False

    return trades

